const won = n => Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',') + '원';
const hash = s => { let h = 5381; for (const c of s) h = ((h * 33) ^ c.codePointAt(0)) >>> 0; return h.toString(36).toUpperCase().slice(-4).padStart(4, '0'); };
const product = $('Copy webhook').first().json.body.product;
const name = String(product.name).trim();
const price = Number(product.price) > 0 ? Math.round(Number(product.price)) : null;
const features = (Array.isArray(product.features) ? product.features : []).map(x => String(x).trim()).filter(Boolean);
const josa = (word, a, b) => { const c = String(word).charCodeAt(String(word).length - 1); if (c >= 0xAC00 && c <= 0xD7A3) return (c - 0xAC00) % 28 ? a : b; return `${a}(${b})`; };
const numbersIn = s => [...String(s).matchAll(/\d[\d,.]*/g)].map(m => m[0].replace(/[,.]+$/, '').replace(/,/g, ''));
let text = String($json.output ?? '').trim().replace(/^```\w*\s*|```$/g, '').replace(/^["“']|["”']$/g, '').trim();
// LLM을 그대로 믿지 않는다: 이름 · 지어낸 숫자 · 가격 · 길이 검사
const allowed = new Set(numbersIn(features.join(' ')));
if (price) allowed.add(String(price));
const problems = [];
if (!text.includes(name)) problems.push('제품 이름이 없음');
const invented = numbersIn(text).filter(n => !allowed.has(n));
if (invented.length) problems.push('입력에 없는 숫자: ' + invented.join(', '));
if (!price && /할인|%|\d\s*원/.test(text)) problems.push('가격 정보가 없는데 가격·할인을 씀');
if (text.length < 80 || text.length > 900) problems.push(`길이 ${text.length}자`);
const source = problems.length ? 'template' : 'llm';
if (problems.length) {
  // 안전한 기본 글: 입력 정보만으로 만든다
  text = `${name}${josa(name, '을', '를')} 소개합니다. `
    + (features.length ? `${features.join(', ')}${josa(features[features.length - 1], '을', '를')} 갖춰 매일 더 편하게 쓸 수 있어요. ` : '')
    + (price ? `가격은 ${won(price)}입니다. ` : '')
    + `지금 ${name}${josa(name, '을', '를')} 만나 보세요.`;
}
return [{ json: { route: '자동 답변', text, answer: text, length: text.length, source, problems } }];
